insert into public.exercise_translations_gymtrack (exercisedb_id, name_pt, instructions_pt) values
  ('Qj0HRAZ', 'Abducao de quadril sentada com elastico', array['Sente-se em uma cadeira ou banco com as costas retas e os pes apoiados', 'Passe o elastico de resistencia ao redor das coxas, logo acima dos joelhos', 'Alinhe a pelve antes de mover a perna de trabalho', 'Abra os joelhos ou as pernas contra a resistencia sem girar o tronco', 'Controle o elastico na volta em vez de deixar que ele puxe voce rapidamente', 'Retorne pelo mesmo caminho em um ritmo controlado']),
  ('QjE2DcA', 'Afundo búlgaro com halteres', array['Posicione-se em frente a um banco ou degrau com um halter em cada mao, palmas voltadas para o corpo', 'Coloque o pe direito no banco ou degrau, garantindo que todo o pe esteja em contato com a superficie', 'Coloque o pe da frente totalmente na plataforma antes de transferir seu peso para ele', 'Suba na plataforma empurrando com o pe da frente para ficar erguido sobre ele', 'Suba com o peito e o quadris subindo juntos; evite que os joelhos caiam para dentro', 'Fique totalmente em pe, ajuste sua postura e resp respiracao, entao comecar a proxima descida']),
  ('qKBpF7I', 'Elevacao pelvica com barra', array['Comece deitado de costas no chao com os joelhos flexionados e os pes apoiados', 'Posicione uma barra sobre os quadris, segurando-a firmemente com ambas as maos', 'Apoie os pes e evite arquear as costelas enquanto os quadris se preparam para subir', 'Empurre pelos pes e eleve os quadris ate que seu tronco e coxas fiquem alinhados', 'Pare quando os quadris estiverem alinhados com o tronco; nao arqueie mais a regiao lombar', 'Abaixe os quadris de forma firme e mantenha os pes apoiados para o proximo movimento']),
  ('Ql4g5s8', 'Afundo frontal', array['Fique em pe com os pes na largura dos quadris e as maos na cintura', 'De um passo largo para a frente com o pe direito, abaixando o corpo em posicao de afundo', 'Abra a base o suficiente para se equilibrar antes de flexionar qualquer um dos joelhos', 'Avance para o movimento e flexione ambos os joelhos, mantendo o pe da frente apoiado', 'Mantenha o pe da frente apoiado e evite que o joelho vire para dentro', 'Empurre o pe da frente para voltar ao inicio, depois alterne as pernas conforme planejado']),
  ('QLL2gdc', 'Abdominal declinado', array['Posicione-se em um banco declinado com os pes presos e os joelhos flexionados', 'Coloque as maos atras da cabeca ou cruzadas no peito', 'Posicione a pelve e mantenha o pescoco relaxado antes de fazer a flexao do tronco', 'Flexione a caixa toracica em direcao a pelve, deixando oabdomen mover o tronco', 'Deixe um pequeno espaco entre o queixo e o peito; mantenha o movimento focado no tronco', 'Abaixe os ombros ou o tronco com controle antes da proxima flexao']),
  ('qLpO4vV', 'Extensao de lombar na bola suica', array['Coloque a bola suica no chao e posicione-se de brucos sobre ela, com os quadris apoiados na bola e os pes contra uma parede ou outra superficie estavel', 'Coloque as maos atras da cabeca ou cruzadas no peito', 'Firme os quadris e os pes no apoio antes de elevar', 'Eleve o tronco ou as pernas ate que fiquem alinhados com o corpo, sem arquear excessivamente a regiao lombar', 'Mantenha a bola firme e use os pes para controlar o equilibrio', 'Retorne pelo mesmo caminho em um ritmo controlado']),
  ('QLRmNeT', 'Rosca martelo alternada sentada na bola suica', array['Sente-se em uma bola suica com os pes apoiados e as costas retas', 'Segure um halter em cada mao com as palmas voltadas para o corpo e os bracos esticados', 'Posicione os ombros e os bracos antes de flexionar os cotovelos', 'Flexione com as palmas voltadas uma para a outra e os cotovelos junto ao corpo; evite balancar para tras', 'Termine o movimento de um lado antes que o outro lado comece', 'Abaixe ate que os bracos estejam quase esticados, mantendo os bracos parados; alterne os lados quando necessario']),
  ('qlZUaZ8', 'Supino inclinado com um haltere na bola suica', array['Sente-se em uma bola suica com um halter em uma das maos e os pes apoiados', 'Com controle, caminhe com os pes para a frente, rolando a bola ate que sua cabeca, pescoco e parte superior das costas estejam apoiados na bola', 'Contraia o tronco e alinhe os punhos com os antebracos', 'Empurre o peso para longe enquanto mantem o tronco contraido', 'Mantenha ambos os ombros nivelados e evite girar em direcao ao braco que esta trabalhando', 'Abaixe o peso ate a altura inicial com controle antes de empurrar novamente; alterne os lados quando necessario']),
  ('qm9veZw', 'Rosca concentrada deitada com halteres', array['Posicione-se em um banco com um halter em cada mão, com as palmas voltadas para cima e os braços esticados', 'Com os braços parados, expire e flexione os pesos contraindo os bíceps', 'Posicione os ombros e a parte superior dos braços antes de dobrar os cotovelos', 'Dobre os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco', 'Mantenha o tronco firme e deixe a flexão do cotovelo levantar o peso', 'Abaixe até que os cotovelos estejam quase retos, mantendo a parte superior dos braços imóvel']),
  ('QOA0FD0', 'Elevação de pernas e quadris suspensa com carga', array['Suspenda-se em uma barra fixa com os braços esticados e as palmas viradas para longe de você', 'Contraia o abdômen e levante as pernas à sua frente, mantendo-as esticadas', 'Apoie os pés e evite estufar as costelas enquanto os quadris se preparam para subir', 'Pressione através dos pés e levante os quadris até que o tronco e as coxas fiquem alinhados', 'Pare quando os quadris estiverem alinhados com o tronco; não arqueie mais a parte inferior das costas', 'Abaixe os quadris de forma constante e mantenha os pés apoiados para a próxima elevação']),
  ('qOgPVf6', 'Rosca scott com barra', array['Sente-se em um banco scott com os braços apoiados no apoio e o peito contra o suporte', 'Segure a barra com as palmas voltadas para cima, um pouco além da largura dos ombros', 'Apoie o braço de trabalho contra o banco scott e deixe o cotovelo livre para dobrar', 'Flexione o peso enquanto os braços permanecem em contato com o apoio', 'Mantenha o tronco firme e deixe a flexão do cotovelo levantar o peso', 'Abaixe até que os cotovelos estejam quase retos, mantendo a parte superior dos braços imóvel']),
  ('QoHIhPl', 'Alongamento de peito atrás da cabeça', array['Fique em pé e posicione os pés na largura dos ombros', 'Entrelace os dedos atrás da cabeça com os cotovelos apontados para fora', 'Entre na posição inicial e respire suavemente antes de aprofundar o movimento', 'Vá em direção ao alongamento até sentir uma tensão leve; continue respirando e evite balançar', 'Mantenha-se em um alongamento leve em vez de puxar mais com impulso', 'Mantenha a posição com respiração constante, depois solte suavemente; repita do outro lado, se necessário']),
  ('qOKcgVP', 'Alongamento de panturrilha em pé', array['Fique de frente para uma parede ou objeto firme, a cerca de um braço de distância', 'Coloque as mãos na parede ou objeto na altura dos ombros', 'Deixe os tornozelos se moverem livremente enquanto o resto do corpo permanece firme', 'Abaixe o calcanhar e desloque o corpo até que a panturrilha estique; mantenha o pé apontado para a frente', 'Faça uma pausa no topo sem girar os tornozelos para fora', 'Abaixe os calcanhares em um ritmo controlado antes de subir novamente']),
  ('QoSZo2Y', 'Supino inclinado com cabo e um braço', array['Ajuste a máquina de cabo na posição de polia baixa', 'Sente-se em um banco inclinado virado para longe da máquina de cabo', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso ou os puxadores para longe, mantendo o tronco contraído', 'Mantenha ambos os ombros nivelados e evite virar-se para o braço em exercício', 'Abaixe o peso até a altura inicial de forma controlada antes de empurrar novamente; alterne os lados quando necessário']),
  ('Qoujh3Q', 'Tiros de velocidade', array['Escolha um espaço aberto ou uma pista para realizar o exercício', 'Comece em pé com os pés na largura dos ombros', 'Inicie em um ritmo que permita que os pés e os braços se movam em sincronia', 'Mova-se em um ritmo repetível, mantendo o movimento suave e a respiração constante', 'Mantenha o padrão repetível conforme a velocidade aumenta', 'Mantenha o ritmo pelo intervalo planejado, desacelerando se a sua forma começar a falhar']),
  ('qPEzJjA', 'Caminhada do fazendeiro', array['Fique em pé com um halter em cada mão, com as palmas voltadas para as coxas', 'Mantenha a coluna em uma posição neutra e confortável e os ombros para trás', 'Fique em pé com a carga segura e os ombros nivelados', 'Caminhe em um ritmo controlado, mantendo os ombros nivelados e os passos firmes', 'Mantenha os passos firmes e evite inclinar-se para longe da carga', 'Pare antes que a postura falhe, apoie a carga com segurança e prepare-se para a próxima caminhada']),
  ('QpXqiq8', 'Afundo búlgaro suspenso', array['Fique de costas para um sistema de suspensão em uma base estável com os pés na largura dos ombros.', 'Leve uma perna para frente e coloque o peito do pé no apoio do sistema de suspensão.', 'Contraia o abdômen e distribua a pressão por todo o pé.', 'Flexione os quadris e os joelhos para descer, mantendo os pés apoiados no chão e os joelhos alinhados com os dedos dos pés.', 'Empurre para cima fazendo o peito e o quadrilsubirem juntos; evite que os joelhos fechem para dentro.', 'Fique totalmente em pé, ajuste sua postura e respiração, e então inicie a próxima descida.']),
  ('Qqi7bko', 'Puxada alta com pegada aberta', array['Suspenda-se em uma barra fixa com as palmas das mãos voltadas para frente e uma abertura maior que a largura dos ombros.', 'Contraia o tronco e aproxime as escápulas uma da outra.', 'Inicie a partir de uma suspensão controlada, com os ombros ativos e não relajados.', 'Puxe os cotovelos para baixo e aproxime a parte superior do peito da barra sem dar impulso com as pernas.', 'Evite balançar as pernas para ultrapassar a barra.', 'Desça até esticar os braços sem soltar o peso abruptamente do alto.']),
  ('QQwxa8g', 'Rosca scott com halter na bola suíça', array['Sente-se em uma bola suíça com os pés apoiados no chão e as costas retas.', 'Segure um halter com uma mão e a palma voltada para cima, apoiando o cotovelo na bola suíça.', 'Apoie a parte superior do braço em trabalho sobre a bola e deixe o cotovelo livre para flexionar.', 'Flexione o peso enquanto os braços permanecem em contato com a bola.', 'Mantenha a bola firme e use os pés para controlar o equilíbrio.', 'Desça até que os braços estejam quase esticados, mantendo a parte superior do braço imóvel.']),
  ('qRZ5S1N', 'Tríceps no cabo com uma mão', array['Fique de frente para uma polia com uma barra reta acoplada na altura do peito.', 'Segure a barra com as palmas voltadas para baixo e dê um passo para trás para tensionar o cabo.', 'Fique a uma distância suficiente da torre para que o cabo permaneça esticado.', 'Mantenha os cotovelos junto às costelas e estenda os braços contra a resistência do cabo.', 'Mantenha ambos os ombros nivelados e evite girar o tronco em direção ao braço que trabalha.', 'Retorne pelo mesmo caminho em ritmo controlado; alterne os lados quando a série exigir.']),
  ('QsSQWbf', 'Elevação de panturrilha invertida com elástico em uma perna', array['Fique em pé com os pés na largura dos quadris e posicione o elástico na planta do pé.', 'Use um objeto estável para manter o equilíbrio.', 'Deixe os tornozelos se moverem livremente enquanto o restante do corpo permanece imóvel.', 'Suba apoiando-se na ponta dos pés, elevando os calcanhares o máximo possível sem balançar.', 'Controle o elástico na volta em vez de deixar que ele puxe você rapidamente.', 'Abaixe os calcanhares em ritmo cadenciado antes de subir novamente.']),
  ('QT5Q0nK', 'Desenvolvimento alternado sentado com halteres', array['Sente-se em um banco com um halter em cada mão e as palmas voltadas para frente.', 'Antes de se mover, eleve os halteres até a altura dos ombros, com os cotovelos flexionados e as palmas voltadas para frente.', 'Contraia o tronco e alinhe os punhos com os antebraços.', 'Empurre o peso para cima mantendo o tronco firme.', 'Complete o movimento de um lado antes de iniciar o outro.', 'Abaixe o peso até a altura inicial de forma controlada antes de empurrar novamente; alterne os lados quando a série exigir.']),
  ('QTXKWPh', 'Rosca direta na polia alta', array['Conecte uma barra reta à polia na regulagem mais alta.', 'Fique de frente para a máquina em uma base estável com os pés na largura dos ombros.', 'Sente-se erguido e posicione os ombros antes de puxar a barra para baixo.', 'Puxe a alça para baixo direcionando os cotovelos em direção às costelas; mantenha o tronco firme.', 'Puxe com os cotovelos em vez de inclinar muito o tronco para trás para mover a carga.', 'Deixe a alça subir de forma controlada até que os braços estejam estendidos, depois reajuste os ombros.']),
  ('qU8bYp7', 'Extensão de tríceps em pé com um braço na polia', array['Fique em pé com os pés na largura dos ombros, de frente para a polia.', 'Segure a alça do cabo com a mão direita, com a palma voltada para baixo, e posicione o braço esticado e paralelo ao chão.', 'Posicione a parte superior do braço firmemente antes de estender o cotovelo.', 'Mantenha a parte superior do braço firme e estenda o cotovelo para mover o peso.', 'Mantenha ambos os ombros nivelados e evite girar o tronco em direção ao braço que trabalha.', 'Flexione os cotovelos lentamente para retornar ao início da próxima repetição; alterne os lados quando a série exigir.']),
  ('QUDd8WS', 'Abdominal oblíquo no solo', array['Deite-se de costas com os joelhos flexionados e os pés apoiados', 'Coloque as mãos atrás da cabeça ou cruze-os sobre o peito', 'Posicione a pelve e mantenha o pescoço relaxado antes de subir', 'Flexione a caixa torácica em direção à pelve, deixando o abdômen mover o tronco', 'Deixe um pequeno espaço entre o queixo e o peito e mantenha o movimento no tronco', 'Desça os ombros ou o tronco com controle antes da próxima repetição']),
  ('qx4fgX7', 'Afundo unilateral com halter', array['Fique em pé com os pés na largura dos ombros, segurando um halter em cada mão', 'Dê um passo à frente com um pé e posicione os pés de forma que o pé da frente fique apoiado no chão e o de trás elevado em um banco ou degrau', 'Contraia o abdômen e distribua a pressão por todo o pé', 'Flexione os quadris e joelhos para descer, mantendo os pés firmes no chão e os joelhos alinhados com os dedos dos pés', 'Empurre para cima com o peito e os quadris subindo juntos, evitando que os joelhos cedessem para dentro', 'Fique totalmente em pé, ajuste sua base e respiração, depois inicie a próxima descida']),
  ('qXTaZnJ', 'Agachamento livre com barra', array['Fique em pé com os pés na largura dos ombros e os dedos levemente virados para fora', 'Apoie a barra na parte superior das costas e faça uma pegada firme', 'Contraia o abdômen e distribua a pressão por todo o pé', 'Flexione os quadris e joelhos para descer, mantendo os pés firmes no chão e os joelhos alinhados com os dedos dos pés', 'Empurre para cima com o peito e os quadris subindo juntos, evitando que os joelhos cedessem para dentro', 'Fique totalmente em pé, ajuste sua base e respiração, depois inicie a próxima descida']),
  ('QY39eBr', 'Alongamento de piriforme sentado', array['Sente-se no chão com as pernas estendidas à sua frente', 'Antes de se mover, flexione o joelho direito e coloque o pé direito do lado de fora do joelho esquerdo', 'Acomode-se na posição inicial e respire calmamente antes de aprofundar o movimento', 'Vá em direção ao alongamento até sentir uma tensão leve, continue respirando e evite balançar', 'Mantenha-se em um alongamento leve em vez de puxar mais com impulso', 'Mantenha a posição com respiração constante, depois solte suavemente e repita do outro lado se necessário']),
  ('Qyk5J3p', 'Rosca martelo cruzada com halter', array['Fique em pé com um halter em cada mão e palmas voltadas para o corpo', 'Mantenha os cotovelos próximos ao tronco e os braços estáticos', 'Posicione os ombros e os braços antes de flexionar os cotovelos', 'Flexione cada peso cruzando o tronco em direção ao ombro oposto, mantendo a palma voltada para dentro', 'Mantenha as palmas voltadas uma para a outra e os punhos retos', 'Abaixe até que os cotovelos estejam quase retos, mantendo os braços parados']),
  ('QyO6Uma', 'Supino declinado com pegada fechada no Smith', array['Ajuste a máquina Smith para a posição declinada', 'Deite-se no banco com os pés presos sob os suportes', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso ou as barras para longe mantendo o tronco contraído', 'Mantenha os punhos alinhados e use uma trajetória de ombro que pareça natural', 'Abaixe o peso até a altura inicial com controle antes de empurrar novamente']),
  ('QYysSLV', 'Rotação de tronco no landmine', array['Fique em pé com os pés na largura dos ombros e segure a barra com as duas mãos à frente do peito', 'Flexione levemente os joelhos e rotacione o tronco para a direita, balançando a barra para baixo em direção ao quadril direito', 'Posicione a pelve e faça o giro através da caixa torácica', 'Gire através do tronco enquanto os quadris e a parte inferior do corpo permanecem o mais firmes possível', 'Mantenha o giro suave em vez de jogar os braços através do corpo', 'Retorne pelo centro antes de girar para o outro lado']),
  ('QZFv5ui', 'Desenvolvimento unilateral com halter na bola suíça', array['Sente-se em uma bola suíça com os pés apoiados e os joelhos flexionados a um ângulo de 90 graus', 'Pegue um halter em uma mão e posicione-o na altura do ombro, com o cotovelo flexionado e a palma voltada para a frente', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso ou as barras para longe mantendo o tronco contraído', 'Mantenha ambos os ombros nivelados e evite girar em direção ao braço que está trabalhando', 'Abaixe o peso até a altura inicial com controle antes de empurrar novamente e alterne os lados quando necessário']),
  ('r0z6xzQ', 'Remada Pendlay com barra', array['Fique em pé com os pés na largura dos ombros e joelhos levemente flexionados', 'Incline-se para a frente a partir dos quadris, com a coluna firme e o peito estufado', 'Posicione o tronco e deixe os braços esticados para a frente sem arredondar excessivamente', 'Puxe os cotovelos para trás e leve a carga em direção ao tronco', 'Traga os cotovelos para trás sem dar trancos com o tronco', 'Estique os braços para a frente novamente sem deixar o tronco balançar']),
  ('R1WYG5D', 'Abdominal remador suspenso', array['Suspenda-se em uma barra fixa com os braços esticados e as palmas das mãos viradas para a frente', 'Contraia o abdômen e levante os joelhos em direção ao peito, curvando a pelve em direção à caixa torácica', 'Estabilize a pelve e mantenha o pescoço relaxado antes de curvar para cima', 'Curve a caixa torácica em direção à pelve, deixando o abdômen mover o tronco', 'Deixe um pequeno espaço entre o queixo e o peito e mantenha o movimento no tronco', 'Abaixe os ombros ou o tronco com controle antes da próxima repetição']),
  ('r1XNRYB', 'Puxada frontal assistida com elástico', array['Prenda o elástico em uma barra fixa ou ponto de ancoragem firme', 'Apoie o pé no elástico e segure a barra com as palmas das mãos viradas para a frente, com as mãos um pouco além da largura dos ombros', 'Comece de uma suspensão controlada com os ombros ativos em vez de relaxados', 'Puxe os cotovelos para baixo e leve a parte superior do peito em direção à barra sem chutar as pernas', 'Controle o elástico na volta em vez de deixar que ele puxe você rapidamente', 'Desça com os braços totalmente esticados sem cair de repente do topo']),
  ('r29jP7S', 'Elevação de panturrilha sentado com halteres', array['Sente-se em um banco ou cadeira com os pés apoiados no chão e um halter apoiado nas coxas', 'Apoie a parte da frente dos pés em uma superfície elevada, como um degrau ou bloco, com os calcanhares para fora da borda', 'Deixe os tornozelos se moverem livremente enquanto o resto do corpo permanece firme', 'Suba na ponta dos pés, levantando os calcanhares o mais alto que puder sem balançar', 'Faça uma pausa no topo sem girar os tornozelos para fora', 'Abaixe os calcanhares em um ritmo controlado antes de subir novamente']),
  ('r4RZKpF', 'Crucifixo com um halter na bola suíça', array['Sente-se em uma bola suíça com um halter em uma das mãos e os pés apoiados no chão', 'Dê um passo à frente com os pés e role o corpo para baixo até que a parte superior das costas esteja apoiada na bola suíça', 'Mantenha uma leve flexão nos cotovelos e estabilize os ombros antes de mover os braços', 'Com uma leve flexão nos cotovelos, junte os braços em um arco amplo', 'Mantenha ambos os ombros nivelados e evite virar o tronco em direção ao braço que está trabalhando', 'Abra os braços de volta pelo mesmo arco sem abaixar a carga e troque de lado quando necessário']),
  ('r5DgrW9', 'Agachamento com suporte de halteres', array['Fique em pé com os pés na largura dos ombros, segurando um halter em cada mão ao lado do corpo', 'Com o peito estufado e o core contraído, abaixe o corpo com controle flexionando os joelhos e empurrando os quadris para trás', 'Contraia o abdômen e distribua a pressão por todo o pé', 'Flexione os quadris e os joelhos para descer, mantendo os pés firmes no chão e os joelhos alinhados com os dedos dos pés', 'Empurre para cima elevando o peito e os quadris juntos e evite que os joelhos desabem para dentro', 'Fique totalmente em pé, ajuste sua postura e respiração e inicie a próxima descida']),
  ('R5swFnc', 'Remada deitada com barra curvada', array['Prepare uma barra no chão e posicione-se de bruços em um banco com o peito logo acima da borda', 'Abaixe-se e segure a barra com as palmas das mãos voltadas para baixo, um pouco além da largura dos ombros', 'Posicione o tronco e deixe os braços esticados para a frente sem arredondar excessivamente', 'Puxe os cotovelos para trás e leve a carga em direção ao tronco', 'Traga os cotovelos para trás sem dar trancos com o tronco', 'Estique os braços para a frente novamente sem deixar o tronco balançar']),
  ('r7cT9YD', 'Rotação russa com movimento assistido', array['Sente-se no chão com os joelhos flexionados e os pés apoiados', 'Segure a bola medicinal com as duas mãos na altura do peito', 'Estabilize a pelve e faça a rotação através da caixa torácica', 'Gire o tronco enquanto os quadris e a parte inferior do corpo permanecem o mais firmes possível', 'Mantenha a rotação suave em vez de lançar os braços de um lado para o outro', 'Retorne ao centro antes de girar para o outro lado']),
  ('RaflbWD', 'Rosca inclinada com halteres', array['Sente-se em um banco inclinado com um halter em cada mão, palmas viradas para a frente e braços esticados.', 'Com os braços parados, expire e levante os pesos contraindo os bíceps.', 'Posicione os ombros e os braços antes de dobrar os cotovelos.', 'Dobre os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco.', 'Mantenha o tronco imóvel e deixe a flexão do cotovelo levantar o peso.', 'Abaixe até que os cotovelos estejam quase retos, mantendo os braços parados.']),
  ('rbu5UUb', 'Abdominal cruzado', array['Deite-se de costas com os joelhos flexionados e os pés apoiados no chão.', 'Coloque as mãos atrás da cabeça com os cotovelos apontados para fora.', 'Posicione a pelve e mantenha o pescoço relaxado antes de subir.', 'Flexione a caixa torácica em direção à pelve, deixando o abdômen mover o tronco.', 'Deixe um pequeno espaço entre o queixo e o peito; mantenha o movimento no tronco.', 'Abaixe os ombros ou o tronco com controle antes da próxima flexão.']),
  ('rDAiRf9', 'Supino inclinado unilateral com halteres', array['Sente-se em um banco inclinado com um halter em uma mão, apoiado na sua coxa.', 'Deite-se no banco e posicione o halter na altura do ombro, com a palma virada para a frente.', 'Contraia o tronco e alinhe os punhos com os antebraços.', 'Empurre o peso para longe enquanto mantém o tronco contraído.', 'Mantenha ambos os ombros nivelados e resista a girar em direção ao braço de trabalho.', 'Abaixe o peso até a altura inicial com controle antes de empurrar novamente; alterne os lados quando necessário.']),
  ('reFHapa', 'Crucifixo declinado com rotação com halteres', array['Deite-se em um banco declinado com a cabeça mais baixa que os quadris.', 'Pegue um halter em cada mão com as palmas viradas uma para a outra e os braços esticados para cima do peito.', 'Mantenha uma leve flexão nos cotovelos e posicione os ombros antes de mover os braços.', 'Com uma leve flexão nos cotovelos, junte os braços em um arco largo.', 'Mantenha o ângulo do cotovelo quase inalterado durante o arco.', 'Abra os braços de volta pelo mesmo arco sem deixar cair a carga.']),
  ('REGM1dE', 'Supino declinado unilateral com halteres', array['Deite-se em um banco declinado com um halter em uma mão, apoiado no seu peito.', 'Mantenha os pés apoiados e as costas pressionadas contra o banco.', 'Contraia o tronco e alinhe os punhos com os antebraços.', 'Empurre o peso para longe enquanto mantém o tronco contraído.', 'Mantenha ambos os ombros nivelados e resista a girar em direção ao braço de trabalho.', 'Abaixe o peso até a altura inicial com controle antes de empurrar novamente; alterne os lados quando necessário.']),
  ('rEhi2o5', 'Supinação deitada no chão com halteres', array['Deite-se de costas no chão com as pernas esticadas e os braços ao lado do corpo, segurando um halter em cada mão.', 'Antes de se mover, rotacione as palmas para cima, mantendo os cotovelos próximos ao corpo.', 'Mantenha os cotovelos relaxados para que os pequenos músculos da mão ou do antebraço suportem a carga.', 'Mova-se pelos punhos ou dedos enquanto os antebraços permanecem apoiados e parados.', 'Use uma amplitude pequena e suave sem balançar os cotovelos.', 'Volte à posição inicial sem deixar a carga cair das suas mãos.']),
  ('REXmfVC', 'Martelo pesado', array['Fique de pé com os pés na largura dos ombros e segure o martelo pesado com as duas mãos.', 'Contraia o tronco e mantenha a coluna em uma posição neutra confortável.', 'Comece em um ritmo que permita que os pés e os braços se movam em sincronia.', 'Balance o martelo para baixo com uma rotação coordenada do quadril, depois reinicie a pegada e a postura.', 'Mantenha as palmas viradas uma para a outra e os punhos retos.', 'Mantenha o ritmo pelo intervalo planejado, diminuindo a velocidade se a forma começar a falhar.']),
  ('rg59QCH', 'Supino no chão unilateral com kettlebell', array['Deite-se de costas no chão com os joelhos flexionados e os pés apoiados no chão.', 'Segure o kettlebell em uma mão com a palma virada para os pés e o braço esticado para cima em direção ao teto.', 'Contraia o tronco e alinhe os punhos com os antebraços.', 'Empurre o peso para longe enquanto mantém o tronco contraído.', 'Mantenha ambos os ombros nivelados e resista a girar em direção ao braço de trabalho.', 'Abaixe o peso até a altura inicial com controle antes de empurrar novamente; alterne os lados quando necessário.']),
  ('RgJDRR1', 'Remada alta com pegada aberta com barra', array['Fique em pé com os pés na largura dos ombros e segure uma barra com as palmas voltadas para baixo e mãos mais afastadas que a largura dos ombros.', 'Mantenha a barra pendurada à frente das coxas com os braços esticados.', 'Posicione o tronco e permita que os braços avancem sem curvar excessivamente.', 'Puxe os cotovelos para trás e leve a barra ou peso em direção ao tronco.', 'Traga os cotovelos para trás sem dar trancos no tronco.', 'Estique os braços novamente para a frente sem deixar o tronco balançar.']),
  ('RGLscZM', 'Agachamento com barra baixa no Smith', array['Prepare a máquina Smith com a barra a uma altura que permita apoiá-la confortavelmente na parte superior das costas.', 'Fique em pé com os pés na largura dos ombros e pontas dos pés levemente voltadas para fora.', 'Contraia o abdômen e distribua a pressão por todo o pé.', 'Flexione os quadris e joelhos para abaixar, mantendo os pés apoiados no chão e os joelhos alinhados com os dedos dos pés.', 'Empurre para cima elevando o peito e os quadris juntos; evite que os joelhos desabem para dentro.', 'Fique totalmente em pé, ajuste sua base e respiração, e inicie a descida seguinte.']),
  ('rGwhJ5o', 'Elevação de panturrilhas em pé com barra', array['Fique em pé com os pés na largura dos ombros e apoie uma barra na parte superior das costas.', 'Antes de se mover, tire os calcanhares do chão o mais alto possível usando as panturrilhas.', 'Deixe os tornozelos se moverem livremente enquanto o resto do corpo permanece firme.', 'Suba apoiando-se na parte frontal dos pés, elevando os calcanhares o máximo que puder sem balançar.', 'Faça uma pausa no topo sem girar os tornozelos para fora.', 'Abaixe os calcanhares em ritmo controlado antes de subir novamente.']),
  ('RJa4tCo', 'Battling ropes', array['Fique em pé com os pés na largura dos ombros e joelhos levemente flexionados.', 'Segure uma ponta da corda em cada mão com as palmas voltadas uma para a outra.', 'Comece em um ritmo que permita aos pés e braços se moverem em sincronia.', 'Mova-se em um ritmo repetível, mantendo o movimento fluido e a respiração constante.', 'Mantenha o padrão repetível conforme a velocidade aumenta.', 'Mantenha o ritmo pelo intervalo planejado, diminuindo a velocidade se a postura começar a falhar.']),
  ('RJgzwny', 'Mountain climber', array['Comece em posição de prancha alta com as mãos diretamente sob os ombros e o corpo em linha reta.', 'Contraia o tronco e traga o joelho direito em direção ao peito, depois alterne rapidamente trazendo o joelho esquerdo para o peito.', 'Contraia levemente o tronco antes de mover um membro.', 'Mova o braço ou a perna em atividade mantendo o tronco firme e a respiração uniforme.', 'Evite que a pélvis balance enquanto o braço ou a perna se movem.', 'Ajuste sua postura antes de trocar de lado ou iniciar a próxima repetição.']),
  ('rjiM4L3', 'Caminhada na esteira inclinada', array['Defina o nível de inclinação da esteira para a intensidade desejada.', 'Suba na esteira com os pés na largura dos ombros.', 'Fique erguido com a carga segura e os ombros nivelados.', 'Caminhe em ritmo controlado, mantendo os ombros nivelados e os passos uniformes.', 'Mantenha os passos uniformes e evite inclinar-se para longe da carga.', 'Pare antes que a postura falhe, apoie a carga com segurança e recomece para a próxima caminhada.']),
  ('rjtuP6X', 'Caminhada no elíptico', array['Defina o nível de resistência e a inclinação do aparelho elíptico para as configurações desejadas.', 'Suba nos pedais do aparelho e segure levemente nos puxadores.', 'Fique erguido com a carga segura e os ombros nivelados.', 'Caminhe em ritmo controlado, mantendo os ombros nivelados e os passos uniformes.', 'Mantenha os passos uniformes e evite inclinar-se para longe da carga.', 'Pare antes que a postura falhe, apoie a carga com segurança e recomece para a próxima caminhada.']),
  ('rkg41Fb', 'Puxada frontal com pegada neutra e dupla alça', array['Ajuste o assento ao seu corpo e acomode-se no aparelho.', 'Segure as alças com as palmas voltadas para baixo e mãos na largura dos ombros.', 'Sente-se erguido e alinhe os ombros antes de puxar a alça para baixo.', 'Puxe a alça para baixo direcionando os cotovelos em direção às costelas; mantenha o tronco firme.', 'Puxe com os cotovelos em vez de inclinar o tronco muito para trás para mover a alça.', 'Deixe a alça subir de forma constante até que os braços estejam esticados, depois reposicione os ombros.']),
  ('RKjH6Lt', 'Prancha lateral', array['Posicione-se de lado com as pernas estendidas e empilhadas uma sobre a outra.', 'Apoie o antebraço no chão diretamente abaixo do ombro, com o cotovelo dobrado em um ângulo de 90 graus.', 'Contraia o abdômen e encontre uma posição que você possa manter sem prender a respiração.', 'Contraia a região central do corpo e mantenha a posição respirando normalmente.', 'Continue respirando de forma constante enquanto mantém a mesma linha corporal.', 'Mantenha a postura pelo tempo planejado e saia dela com controle.']),
  ('rmEukuS', 'Elevação pélvica unilateral com perna estendida', array['Deite-se de costas com os joelhos flexionados e os pés apoiados no chão.', 'Estique uma perna para a frente.', 'Ajuste-se na posição inicial e respire calmamente antes de aprofundar o movimento.', 'Aproxime-se do ósso até sentir uma tensão leve; continue respirando e evite dar trancos.', 'Permaneça em um leve alinhamento em vez de puxar mais com impulso.', 'Mantenha a posição com respiração constante e solte suavemente; repita do outro lado se necessário.']),
  ('RoV1Rfa', 'Alongamento assistido sentado para peitoral maior com bola suíça', array['Sente-se em uma bola suíça com os pés apoiados e as costas retas.', 'Segure uma bola suíça com ambas as mãos e estenda os braços para a frente.', 'Ajuste-se na posição inicial e respire calmamente antes de aprofundar o movimento.', 'Aproxime-se do ósso até sentir uma tensão leve; continue respirando e evite dar trancos.', 'Mantenha a bola firme e use os pés para controlar o equilíbrio.', 'Mantenha a posição com respiração constante e solte suavemente; repita do outro lado se necessário.']),
  ('rQhGcin', 'Plank de sapo', array['Entre em posição de prancha com os braços estendidos, mãos abaixo dos ombros e pés juntos.', 'Flexione os cotovelos e abaixe o corpo em direção ao chão, mantendo a coluna firme.', 'Contraia o abdômen e encontre uma posição que você possa manter sem prender a respiração.', 'Contraia a região central do corpo e mantenha a posição respirando normalmente.', 'Continue respirando de forma constante enquanto mantém a mesma linha corporal.', 'Mantenha a postura pelo tempo planejado e saia dela com controle.']),
  ('RQNVT10', 'Alongamento assistido deitado para glúteos e piriforme', array['Deite-se de costas com as pernas estendidas.', 'Antes de se mover, dobre o joelho direito e coloque o tornozelo direito sobre a coxa esquerda, logo acima do joelho.', 'Ajuste-se na posição inicial e respire calmamente antes de aprofundar o movimento.', 'Aproxime-se do ósso até sentir uma tensão leve; continue respirando e evite dar trancos.', 'Permaneça em um leve alongamento em vez de puxar mais com impulso.', 'Mantenha a posição com respiração constante e solte suavemente; repita do outro lado se necessário.']),
  ('RqOtqD7', 'Abdominal remador na polia', array['Conecte um cabo a uma polia baixa e deite-se de barriga para cima em um colchonete.', 'Segure o cabo com ambas as mãos e estenda os braços para cima em direção ao teto.', 'Posicione a pelve e mantenha o pescoço relaxado antes de iniciar a flexão para cima.', 'Enrole a caixa torácica em direção à pelve, permitindo que o abdômen mova o tronco.', 'Deixe um pequeno espaço entre o queixo e o peito; mantenha o movimento focado no tronco.', 'Abaixe os ombros ou o tronco com controle antes da próxima repetição.']),
  ('rQxwMxO', 'Flexão em parada de mão', array['Escolha uma parede e fique de costas para ela, a alguns passos de distância.', 'Apoie as mãos no chão na largura dos ombros e jogue os pés para cima contra a parede, assumindo a posição de parada de mão.', 'Contraia o abdômen e encontre uma posição que você possa manter sem prender a respiração.', 'Contraia a região central do corpo e mantenha a posição respirando normalmente.', 'Continue respirando de forma constante enquanto mantém a mesma linha corporal.', 'Mantenha a postura pelo tempo planejado e saia dela com controle.']),
  ('rR0LJzx', 'Stiff com halteres', array['Fique em pé com os pés na largura dos ombros, segurando um halter em cada mão com as palmas voltadas para baixo.', 'Com as costas retas e o core contraído, flexione o quadril e desça os halteres em direção ao chão, permitindo que os joelhos flexionem levemente.', 'Destrave os joelhos e contraia o abdômen antes de mover o quadril para trás.', 'Envie o quadril para trás com uma leve flexão dos joelhos, abaixando a carga perto das pernas até sentir os posteriores de coxa alongarem.', 'Mantenha o peso próximo às pernas e pare quando as costas começarem a curvar.', 'Empurre o quadril para a frente para ficar em pé, sem se inclinar para trás no topo.']),
  ('Rr7S3yg', 'Elevação frontal com halteres', array['Fique de pé com os pés na largura dos ombros, segurando um halter em cada vão com as palmas voltadas para as coxas', 'Mantenha a coluna em uma posição neutra e confortável, e contraia o tronco', 'Começue com uma carga gerenciável e uma leve flexão nos cotovelos', 'Eleve os braços para a frente até a altura dos ombros, mantendo as costelas para baixo e o tronco parado', 'Pare próximo à altura dos ombros em vez de encolher os ombros para subir mais', 'Abaixe os braços lentamente para as laterais sem balançar o peso']),
  ('RrLske5', 'Mergulho no banco (joelhos flexionados)', array['Sente-se na borda de um banco ou cadeira com as mãos segurando a borda ao lado dos quadris', 'Desloque o bumbum para fora do banco e estique as pernas à sua frente, mantendo os calcanhares no chão', 'Posicione os ombros para baixo e mantenha os cotovelos apontados principalmente para trás', 'Flexione os cotovelos para descer entre os apoios; pare em uma profundidade confortável para os ombros', 'Escolha uma profundidade que permita manter os ombros confortáveis', 'Pressione com as mãos para subir, então ajuste os ombros antes de outra repetição']),
  ('RRWFUcw', 'Afundo com halteres', array['Fique de pé com os pés na largura dos ombros, segurando um halter em cada mão', 'Dê um passo à frente com o pé direito, baixando o corpo em uma posição de afundo', 'Deixe sua base larga o suficiente para se equilibrar antes de flexionar qualquer joelho', 'Avance no movimento e flexione ambos os joelhos, mantendo o pé da frente apoiado', 'Mantenha o pé da frente apoiado e evite fechar o joelho para dentro', 'Empurre com o pé da frente para voltar ao início, então alterne as pernas conforme planejado']),
  ('rseLfH3', 'Desenvolvimento Unilateral com Kettlebell com Amplitude Estendida no Chão', array['Começue deitado de costas no chão com os joelhos flexionados e os pés apoiados', 'Pegue um kettlebell com uma mão, com a palma voltada para os seus pés', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Pressione o peso ou as alças para longe enquanto mantém o tronco contraído', 'Mantenha ambos os ombros nivelados e evite virar em direção ao braço que trabalha', 'Abaixe o peso até a altura inicial com controle antes de pressionar novamente; troque de lado quando a série pedir']),
  ('RSOsp5d', 'Volta ao mundo em pé com halteres', array['Fique de pé com os pés na largura dos ombros e segure um halter em cada mão', 'Estique os braços para as laterais na altura dos ombros, com as palmas voltadas para baixo', 'Começue com uma carga gerenciável e uma leve flexão nos cotovelos', 'Conduza os pesos em um arco circular amplo sem inclinar ou balançar', 'Pare próximo à altura dos ombros em vez de encolher os ombros para subir mais', 'Abaixe os braços lentamente para as laterais sem balançar o peso']),
  ('Rsxr3xl', 'Unilateral contra a parede', array['Fique de frente para a parede com uma base estável e os pés na largura dos ombros', 'Estique um braço à frente do corpo e apoie a palma contra a parede', 'Contraia o abdômen e encontre uma posição que possa manter sem prender a respiração', 'Contraia o abdômen e mantenha a posição enquanto respira normalmente', 'Mantenha ambos os ombros nivelados e evite virar em direção ao braço que trabalha', 'Mantenha a postura pelo tempo planejado, então saia dela com controle; troque de lado quando a série pedir']),
  ('rTbyBYV', 'Alongamento lateral deitado na bola suíça', array['Deite-se de lado com as pernas estendidas e a cabeça apoiada na bola suíça', 'Apoie o braço de cima na bola para ter estabilidade', 'Entre na posição inicial e respire suavemente antes de aprofundar o movimento', 'Aproxime-se do alongamento até sentir uma tensão leve; continue respirando e evite dar trancos', 'Mantenha a bola firme e use os pés para controlar seu equuíbrio', 'Mantenha a posição respirando calmamente, então solte devagar; repita do outro lado se necessário']),
  ('RtyAsy1', 'Toque nos dedos dos pés com os braços abertos', array['Fique de pé com os pés na largura dos ombros e os braços estendidos para as laterais', 'Com as pernas esticadas, flexione o tronco para a frente e alcance os dedos dos pés com a mão direita', 'Flexione levemente os joelhos e deixe o quadril iniciar a dobra', 'Dobre o tronco para a frente a partir do quadril e deixe as mãos irem em direção aos pés sem forçar o alcance', 'Mantenha o movimento controlado por toda a amplitude', 'Segure brevemente em uma profundidade confortável, então suba estendendo o quadril']),
  ('rUXfn3R', 'Extensão de lombar na máquina', array['Ajuste a máquina para o tamanho do seu corpo e amplitude de movimento.', 'Sente-se na máquina com as costas apoiadas no encosto e os pés fixos.', 'Fixe o quadril e os pés no suporte antes de levantar.', 'Eleve o tronco ou as pernas até alinharem com o corpo, sem arquear acentuadamente a lombar.', 'Finalize com o corpo em linha reta, antes que a lombar arqueie demais.', 'Retorne suavemente à posição inicial antes de repetir.']),
  ('RVwzP10', 'Puxada com cabo', array['Ajuste a máquina de puxada para que o assento fique em uma altura confortável e o apoio de joelhos esteja fixo.', 'Sente-se com a coluna reta e os pés apoiados no chão.', 'Sente-se erguido e alinhe os ombros antes de puxar a barra.', 'Puxe o puxador levando os cotovelos em direção às costelas; mantenha o tronco firme.', 'Puxe com os cotovelos em vez de inclinar muito o tronco para trás.', 'Deixe o cabo subir de forma controlada até os braços esticarem, depois ajuste os ombros.']),
  ('rWoBmi5', 'Mergulho coreano', array['Posicione-se entre duas barras paralelas com os braços estendidos e sustentando o peso do corpo.', 'Antes de se mover, abaixe o corpo flexionando os cotovelos até que os braços fiquem paralelos ao chão.', 'Abaixe os ombros e mantenha os cotovelos apontados principalmente para trás.', 'Flexione os cotovelos para descer entre os suportes; pare em uma profundidade confortável para os ombros.', 'Escolha uma profundidade que mantenha os ombros confortáveis.', 'Empurre com as mãos para subir, depois ajuste os ombros antes da próxima repetição.']),
  ('RxayqAZ', 'Supino com halteres com pegada fechada', array['Sente-se em um banco reto com um haltere em cada mão, apoiados nas coxas.', 'Use as coxas para ajudar a levantar os halteres, erguendo-os um de cada vez para segurá-los na frente do corpo na largura dos ombros.', 'Contraia o tronco e alinhe os punhos com os antebraços.', 'Empurre o peso para longe enquanto mantém o tronco firme.', 'Mantenha os punhos alinhados e use uma trajetória de ombro que pareça natural.', 'Abaixe o peso até a altura inicial de forma controlada antes de empurrar novamente.']),
  ('RYcV1kH', 'Agachamento com barra e salto com avanço reverso', array['Comece em pé com os pés na largura dos ombros, segurando uma barra na parte superior das costas.', 'Antes de se mover, abaixe o corpo em posição de agachamento flexionando os joelhos e empurrando o quadril para trás.', 'Contraia o abdômen e distribua a pressão por todo o pé.', 'Flexione o quadril e os joelhos para descer, mantendo os pés apoiados e os joelhos alinhados com os dedos dos pés.', 'Empurre para cima com o peito e o quadril subindo juntos; evite que os joelhosandem para dentro.', 'Fique totalmente em pé, ajuste sua base e respiração, depois inicie a próxima descida.']),
  ('rZ80Gbp', 'Rosca concentrada com um braço no cabo', array['Apoie ambos os pés no chão sentado em um banco; com as costas retas.', 'Segure o puxador do cabo com uma mão e apoie o cotovelo na parte interna da coxa, logo acima do joelho.', 'Posicione os ombros e os braços antes de flexionar os cotovelos.', 'Flexione os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco.', 'Mantenha ambos os ombros nivelados e evite girar em direção ao braço que está trabalhando.', 'Abaixe até que os cotovelos estejam quase esticados, mantendo a parte superior dos braços imóvel; troque de lado quando necessário.']),
  ('s0HKO2I', 'Extensão de tríceps de joelhos com o peso corporal', array['Ajoelhe-se no chão com os joelhos na largura do quadril.', 'Apoie as mãos no chão à sua frente, na largura dos ombros, com os dedos apontados para a frente.', 'Posicione a parte superior dos braços antes de estender os cotovelos.', 'Mantenha a parte superior dos braços firme e estenda os cotovelos para mover o peso.', 'Mantenha a parte superior dos braços firme enquanto os antebraços se movimentam.', 'Flexione os cotovelos lentamente para retornar ao início da próxima repetição.']),
  ('S1JXDAG', 'Rotação sentada com elástico', array['Sente-se no chão com as pernas estendidas à sua frente e as costas retas.', 'Passe o elástico ao redor da cintura e segure as pontas com ambas as mãos.', 'Estabilize a pelve e realize o giro através da caixa torácica.', 'Gire o tronco enquanto o quadril e a parte inferior do corpo permanecem o mais firmes possível.', 'Controle o elástico na volta em vez de deixar que ele puxe você rapidamente.', 'Retorne pelo centro antes de girar para o outro lado.']),
  ('s34Y4LR', 'Rotação de tronco sentado (na bola suíça)', array['Sente-se em uma bola suíça com os pés apoiados e os joelhos flexionados em um ângulo de 90 graus.', 'Segure uma anilha ou haltere com ambas as mãos próximas ao peito.', 'Posicione a pelve e realize o giro através da caixa torácica.', 'Gire o tronco enquanto o quadril e a parte inferior do corpo permanecem o mais estáveis possível.', 'Mantenha a bola estável e use os pés para controlar o seu equilíbrio.', 'Retorne ao centro antes de girar para o outro lado.']),
  ('S37C94C', 'Desenvolvimento unilateral com kettlebell', array['Fique de pé com os pés na largura dos ombros, segurando um kettlebell em uma das mãos na altura do ombro.', 'Flexione levemente os joelhos e contraia o abdômen.', 'Estabilize antes da puxada e mantenha a carga próxima ao corpo.', 'Impulsione com as pernas e o quadril, e então guie o peso para a posição de recepção.', 'Mantenha ambos os ombros nivelados e resista à tendência de girar em direção ao braço em movimento.', 'Fique totalmente em pé para finalizar, abaixe o peso de forma controlada antes da próxima repetição e alterne os lados quando necessário.']),
  ('S4pwGlc', 'Agachamento com salto e halteres', array['Fique de pé com os pés na largura dos ombros, segurando um haltere em cada mão ao lado do corpo.', 'Antes de se mover, abaixe o corpo em uma posição de agachamento flexionando os joelhos e empurrando o quadril para trás.', 'Contraia o abdômen e distribua a pressão por todo o pé.', 'Flexione o quadril e os joelhos para descer, mantendo os pés firmes no chão e os joelhos alinhados com os dedos dos pés.', 'Empurre para cima com o peito e o quadril subindo juntos, evitando que os joelhos caiam para dentro.', 'Fique totalmente em pé, ajuste sua base e respiração, e então inicie a próxima descida.']),
  ('s5PdDyY', 'Supino Tate com halteres', array['Sente-se em um banco plano com um haltere em cada mão, com as palmas voltadas uma para a outra.', 'Eleve os halteres até a altura dos ombros e rotacione os punhos para que as palmas fiquem voltadas para frente.', 'Contraia o tronco e alinhe os punhos com os antebraços.', 'Pressione o peso ou as alças para longe enquanto mantém o tronco contraído.', 'Mantenha os punhos alinhados e use uma trajetória de ombro que pareça natural.', 'Abaixe o peso até a altura inicial de forma controlada antes de empurrar novamente.']),
  ('s7HX1BY', 'Agachamento sumô com barra', array['Fique de pé com os pés mais afastados que a largura dos ombros, com os dedos dos pés apontados levemente para fora.', 'Apoie a barra na parte superior das costas e faça uma pegada firme.', 'Contraia o abdômen e distribua a pressão por todo o pé.', 'Flexione o quadril e os joelhos para descer, mantendo os pés firmes no chão e os joelhos alinhados com os dedos dos pés.', 'Empurre para cima com o peito e o quadril subindo juntos, evitando que os joelhos caiam para dentro.', 'Fique totalmente em pé, ajuste sua base e respiração, e então inicie a próxima descida.']),
  ('S8mo30S', 'Elevação frontal em pé com barra acima da cabeça', array['Fique de pé com os pés na largura dos ombros, segurando uma barra à frente das coxas com as palmas para baixo.', 'Mantenha a coluna em uma posição neutra e confortável, e contraia o tronco.', 'Comece com uma carga gerenciável e uma pequena flexão nos cotovelos.', 'Eleve os braços para a frente até a altura dos ombros, mantendo as costelas para baixo e o tronco imóvel.', 'Pare próximo à altura dos ombros em vez de encolher os ombros para levantar mais alto.', 'Abaixe os braços lentamente para os lados sem balançar o peso.']),
  ('s8nrDXF', 'Abdominal com peso', array['Deite-se de costas com os joelhos flexionados e os pés apoiados.', 'Segure uma anilha ou haltere sobre o peito.', 'Posicione a pelve e mantenha o pescoço relaxado antes de enrolar o tronco para cima.', 'Enrole a caixa torácica em direção à pelve, permitindo que o abdômen movimente o tronco.', 'Deixe um pequeno espaço entre o queixo e o peito e mantenha o movimento focado no tronco.', 'Abaixe os ombros ou o tronco com controle antes da próxima flexão.']),
  ('S93zLTG', 'Desenvolvimento para ombros sentado com elástico', array['Sente-se em uma cadeira ou banco com as costas retas e os pés apoiados.', 'Segure a faixa de resistência com ambas as mãos, palmas voltadas para a frente, e traga-a até o nível dos ombros.', 'Contraia o tronco e alinhe os punhos com os antebraços.', 'Pressione o peso ou as alças para longe enquanto mantém o tronco contraído.', 'Controle o elástico na volta em vez de deixar que ele puxe você de volta abruptamente.', 'Abaixe o peso até a altura inicial de forma controlada antes de empurrar novamente.']),
  ('s999Hdo', 'Rosca concentrada unilateral com halteres na bola suíça', array['Sente-se em uma bola suíça com os pés firmes no chão e a coluna reta', 'Segure um halter em uma mão com a palma virada para cima e o braço esticado', 'Posicione os ombros e a parte superior dos braços antes de dobrar os cotovelos', 'Dobre os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco', 'Mantenha ambos os ombros nivelados e evite girar em direção ao braço que está trabalhando', 'Abaixe até que os cotovelos estejam quase retos, mantendo a parte superior dos braços imóvel; troque de lado quando necessário']),
  ('S9zHIvU', 'Remada alta com barra', array['Fique em pé com os pés na largura dos ombros e os joelhos levemente flexionados', 'Segure uma barra com as palmas viradas para baixo e as mãos logo acima da largura dos ombros', 'Posicione o tronco e permita que os braços se estendam para a frente sem curvar excessivamente', 'Puxe os cotovelos para trás e traga a barra ou o peso em direção ao tronco', 'Traga os cotovelos para trás sem dar trancos no tronco', 'Estique os brazos para a frente novamente sem deixar o tronco balançar']),
  ('Sa8mzWc', 'Elevação de pernas suspensa', array['Suspenda-se em uma barra fixa com os braços esticados e as palmas viradas para longe de você', 'Contraia o abdômen e levante as pernas em direção à barra, mantendo-as esticadas', 'Contraia o abdômen e mantenha os ombros fixos no suporte', 'Levante as pernas contraindo o abdômen e movendo-se a partir dos quadris, em vez de balançar', 'Desacelere as pernas antes que elas tirem a parte inferior das costas da posição correta', 'Abaixe as pernas lentamente sem balançar ou perder a posição do tronco']),
  ('SaDOwk7', 'Salto para trás', array['Fique em pé com os pés na largura dos ombros', 'Antes de se mover, flexione levemente os joelhos e salte para trás, impulsionando-se com os dois pés', 'Flexione levemente os quadris e os joelhos para preparar o salto', 'Carregue as pernas com uma pequena flexão, depois empurre o chão e aterre suavemente', 'Aterre com os quadris e os joelhos flexionados e deixe os pés absorverem o impacto', 'Absorva a aterrissagem através dos quadris e dos joelhos antes de repetir']),
  ('Ser9eQp', 'Tríceps na máquina', array['Ajuste o assento ao seu corpo e acomode-se na máquina', 'Segure os puxadores com as palmas viradas para baixo e estique os braços na sua frente', 'Posicione a parte superior dos braços antes de estender os cotovelos', 'Mantenha a parte superior dos braços firme e estenda os cotovelos para mover o peso', 'Mantenha a parte superior dos braços firme enquanto os antebraços se movimentam', 'Dobre os cotovelos lentamente para retornar ao início da próxima repetição']),
  ('SGY8Zui', 'Arremesso com barra', array['Fique em pé com os pés na largura dos ombros e a barra no chão à sua frente', 'Flexione os joelhos e incline-se nos quadris para abaixar e segurar a barra com as palmas viradas para baixo, com as mãos logo acima da largura dos ombros', 'Contraia o abdômen antes da puxada e mantenha a carga perto do corpo', 'Impulsione através das pernas e dos quadris, depois guie o peso para a posição de recepção', 'Receba a carga com o tronco contraído e os pés estáveis', 'Fique em pé erguido para finalizar, depois abaixe o peso de forma controlada antes da próxima repetição']),
  ('SHUMp5H', 'Supino declinado com pegada neutra e um halter', array['Acomode-se em um banco declinado com um halter em uma mão, apoiado no peito', 'Estenda o braço para cima mantendo o cotovelo levemente flexionado', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso para longe enquanto mantém o tronco contraído', 'Mantenha ambos os ombros nivelados e evite girar em direção ao braço que está trabalhando', 'Abaixe o peso até a altura inicial de forma controlada antes de empurrar novamente; troque de lado quando necessário']),
  ('SiWCcTN', 'Levantamento terra olímpico', array['Comece com a barra no chão à sua frente, com os pés na largura dos ombros', 'Abaixe-se e segure a barra com as palmas viradas para baixo, logo acima da largura dos ombros', 'Contraia o abdômen antes da puxada e mantenha a carga perto do corpo', 'Impulsione através das pernas e dos quadris, depois guie o peso para a posição de recepção', 'Receba a carga com o tronco contraído e os pés estáveis', 'Fique em pé erguido para finalizar, depois abaixe o peso de forma controlada antes da próxima repetição']),
  ('SJAA2IQ', 'Rosca de punho com barra com pegada supinada sobre o banco', array['Apoie os dois pés sentado em um banco e segure uma barra com as palmas voltadas para cima', 'Apoie os antebraços no banco, deixando os punhos livres além da borda', 'Mantenha os cotovelos relaxados para que os pequenos músculos da mão ou do antebraço suportem a carga', 'Movimente os punhos ou dedos enquanto os antebraços permanecem apoiados e parados', 'Use uma amplitude pequena e suave sem balançar os cotovelos', 'Retorne à posição inicial com controle sem deixar a carga escapar das suas mãos']),
  ('sJElUUI', 'Desenvolvimento com um halter com apoio na bola suíça', array['Sente-se em uma bola suíça com um halter em uma das mãos e os pés apoiados no chão', 'Com controle, caminhe com os pés para a frente, rolando a bola até que sua cabeça, pescoço e parte superior das costas estejam apoiados na bola', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso para longe enquanto mantém o tronco firme', 'Mantenha ambos os ombros nivelados e evite girar em direção ao braço que está trabalhando', 'Abaixe o peso até a altura inicial com controle antes de empurrar novamente; alterne os lados quando necessário']),
  ('sJFIDIp', 'Rosca concentrada na perna', array['Sente-se em um banco com as pernas afastadas e os pés apoiados no chão', 'Pegue um halter com uma mão e coloque o cotovelo na parte interna da coxa, logo acima do joelho', 'Posicione os ombros e os braços antes de flexionar os cotovelos', 'Flexione os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco', 'Mantenha o tronco parado e deixe a flexão do cotovelo levantar o peso', 'Abaixe até que os cotovelos estejam quase retos, mantendo os braços parados']),
  ('SJqRxOt', 'Remada sentada com cabo e corda', array['Sente-se na máquina de remada com os pés apoiados nos suportes e os joelhos semiflexionados', 'Segure as cordas do cabo com as palmas voltadas para baixo e uma para a outra', 'Posicione o tronco e permita que os braços se estendam para a frente sem curvar excessivamente', 'Puxe os cotovelos para trás e traga a alça ou o peso em direção ao tronco', 'Traga os cotovelos para trás sem dar trancos no tronco', 'Estenda os braços para a frente novamente sem deixar o tronco inclinar bruscamente']),
  ('SKXQAx3', 'Abdominal reverso com rolo', array['Deite-se de costas com os braços estendidos acima da cabeça e as pernas esticadas à sua frente', 'Posicione o rolo entre os pés e segure-o com os dedos dos pés', 'Posicione a pelve e mantenha o pescoço relaxado antes de subir', 'Flexione a caixa torácica em direção à pelve, permitindo que o abdômen movimente o tronco', 'Deixe um pequeno espaço entre o queixo e o peito; mantenha o movimento focado no tronco', 'Abaixe os ombros ou o tronco com controle antes da próxima repetição']),
  ('slDvUAU', 'Rosca martelo com halteres', array['Fique em pé com um halter em cada mão e as palmas voltadas para o tronco', 'Mantenha os cotovelos próximos ao tronco e gire as palmas das mãos até que estejam voltadas para a frente', 'Posicione os ombros e os braços antes de flexionar os cotovelos', 'Faça a rosca com as palmas voltadas uma para a outra e os cotovelos próximos às costelas; evite balançar o corpo', 'Mantenha as palmas voltadas uma para a outra e os punhos retos', 'Abaixe até que os cotovelos estejam quase retos, mantendo os braços parados']),
  ('SLKj2pX', 'Abdominal casulo', array['Deite-se de costas com os joelhos flexionados e os pés apoiados no chão', 'Posicione as mãos atrás da cabeça com os cotovelos apontados para fora', 'Posicione a pelve e mantenha o pescoço relaxado antes de subir', 'Flexione a caixa torácica em direção à pelve, permitindo que o abdômen movimente o tronco', 'Deixe um pequeno espaço entre o queixo e o peito; mantenha o movimento focado no tronco', 'Abaixe os ombros ou o tronco com controle antes da próxima repetição']),
  ('sM84pE4', 'Alongamento de dorsais na bola suíça', array['Sente-se em uma bola de estabilidade com os pés apoiados e as costas retas', 'Pegue um halter com uma mão e estenda o braço para cima, acima da cabeça', 'Acomode-se na posição inicial e respire fundo antes de aprofundar o movimento', 'Vá em direção ao alongamento até sentir uma leve tensão; continue respirando e evite dar trancos', 'Mantenha a bola firme e use os pés para controlar o equilíbrio', 'Mantenha a posição respirando calmamente e solte com cuidado; repita do outro lado, se necessário']),
  ('Sn8wxAI', 'Abdominal crunch (na bola suíça, com braços estendidos)', array['Sente-se na bola suíça com os pés apoiados e os joelhos flexionados a 90 graus', 'Apoie-se na bola até que sua região lombar esteja firme e seu tronco paralelo ao chão', 'Posicione a pelve e mantenha o pescoço relaxado antes de subir', 'Flexione a caixa torácica em direção à pelve, permitindo que o abdômen mova o tronco', 'Mantenha a bola firme e use os pés para controlar o equilíbrio', 'Abaixe os ombros ou o tronco com controle antes da próxima repetição']),
  ('SNFfUff', 'Elevação pélvica com barra', array['Deite-se de costas em um banco com os pés apoiados e os joelhos flexionados', 'Segure a barra com as palmas voltadas para baixo e posicione-a sobre o quadril', 'Apoie os pés e evite estufar as costelas enquanto o quadril se prepara para subir', 'Empurre com os pés e eleve o quadril até que o tronco e as coxas fiquem alinhados', 'Pare quando o quadril estiver alinhado com o tronco, sem arquear excessivamente a região lombar', 'Abaixe o quadril de forma constante e mantenha os pés apoiados para a próxima elevação']),
  ('Snj1wSv', 'Flexão pliométrica', array['Comece em posição de prancha alta com as mãos ligeiramente além da largura dos ombros', 'Abaixe o peito em direção ao chão flexionando os cotovelos, mantendo o corpo em linha reta', 'Contraia o abdômen e os glúteos para que ombros, quadris e tornozelos se movam juntos', 'Flexione os cotovelos para abaixar o peito mantendo o corpo alinhado', 'Mantenha a cabeça alinhada com a coluna enquanto os cotovelos flexionam', 'Empurre de volta à posição de braços estendidos, mantendo o alinhamento do corpo']),
  ('soIB2rj', 'Flexão diamante', array['Comece em posição de prancha alta com as mãos próximas, formando um diamante com os polegares e indicadores', 'Mantenha o corpo em linha reta da cabeça aos pés, ativando o core e os glúteos', 'Contraia o abdômen e os glúteos para que ombros, quadris e tornozelos se movam juntos', 'Flexione os cotovelos para abaixar o peito mantendo o corpo alinhado', 'Mantenha a cabeça alinhada com a coluna enquanto os cotovelos flexionam', 'Empurre de volta à posição de braços estendidos, mantendo o alinhamento do corpo']),
  ('SP3hUez', 'Nado em decúbito ventral', array['Posicione-se de bruços em um colchonete com os braços estendidos acima da cabeça', 'Contraia o tronco e levante o peito e as pernas do chão simultaneamente', 'Contraia levemente o tronco antes de mover um membro', 'Mova o braço ou a perna em atividade mantendo o tronco firme e a respiração constante', 'Evite balançar a pelve enquanto o braço ou a perna se movem', 'Reajuste sua postura antes de trocar de lado ou iniciar a próxima repetição']),
  ('SpsOSXk', 'Puxada alta na polia', array['Ajuste a máquina de cabo para que a polia fique na posição mais alta', 'Sente-se de frente para a máquina com os pés apoiados e os joelhos semiflexionados', 'Sente-se erguido e alinhe os ombros antes de puxar a barra para baixo', 'Puxe a barra para baixo direcionando os cotovelos em direção às costelas e mantenha o tronco firme', 'Puxe com os cotovelos em vez de se inclinar muito para trás para mover a barra', 'Deixe a barra subir de forma controlada até que os braços estejam estendidos, depois reajuste os ombros']),
  ('SpYC0Kp', 'Supino reto com halteres', array['Deite-se em um banco com os pés apoiados e as costas firmes contra o estofado', 'Segure um halter em cada mão, com as palmas voltadas para a frente e os braços estendidos acima do peito', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso para cima mantendo o tronco contraído', 'Mantenha os punhos alinhados e use uma trajetória natural para os ombros', 'Abaixe o peso até a altura inicial com controle antes de empurrar novamente']),
  ('SSsBDwB', 'Afundo reverso com halteres', array['Fique em pé com os pés na largura dos ombros, segurando um halter em cada mão', 'Dê um passo para trás com o pé direito, abaixando o corpo em posição de afundo', 'Ajuste sua base com largura suficiente para manter o equilíbrio antes de flexionar os joelhos', 'Entre no movimento e flexione ambos os joelhos, mantendo o pé da frente apoiado', 'Mantenha o pé da frente apoiado e evite inclinar o joelho para dentro', 'Empurre com o pé da frente para retornar ao início e alterne as pernas conforme planejado']),
  ('sTfvVsG', 'Crucifixo inverso com elástico', array['Conecte o elástico a um objeto fixo na altura do peito.', 'Fique em pé com os pés na largura dos ombros e segure o elástico com as duas mãos na sua frente.', 'Mantenha os cotovelos levemente flexionados e alinhe os ombros antes de mover os braços.', 'Abra os braços para fora e para trás com uma leve flexão nos cotovelos, unindo as escápulas.', 'Controle o elástico na volta em vez de deixar que ele puxe você de repente.', 'Abra os braços para trás pelo mesmo arco sem abaixar a carga.']),
  ('sTg7iys', 'Elevação frontal com elástico', array['Fique em pé com os pés na largura dos ombros e segure o elástico na frente das coxas com as palmas das mãos viradas para baixo.', 'Mantenha os braços esticados e levante o elástico à sua frente até que os braços fiquem paralelos ao chão.', 'Comece com uma carga gerenciável e uma pequena flexão nos cotovelos.', 'Eleve os braços para os lados até a altura dos ombros, sem inclinar o tronco ou encolher os ombros.', 'Controle o elástico na volta em vez de deixar que ele puxe você de repente.', 'Abaixe os braços lentamente para os lados sem balançar o peso.']),
  ('sU5BrfP', 'Alongamento de posterior de coxa com perna para cima', array['Deite-se de costas com as pernas estendidas.', 'Dobre um joelho e traga-o em direção ao peito, segurando a coxa ou a canela.', 'Acomode-se na posição inicial e respire calmamente antes de aprofundar o movimento.', 'Aproxime-se do alongamento até sentir uma tensão leve; continue respirando e evite balançar.', 'Mantenha um alongamento leve em vez de puxar mais com impulso.', 'Mantenha a posição com respiração constante, depois solte suavemente; repita do outro lado, se necessário.']),
  ('sVQCCeG', 'Marcha na parede', array['Fique em pé com as costas apoiadas na parede e os pés na largura dos quadris.', 'Com controle, deslize as costas pela parede até que os joelhos fiquem flexionados em um ângulo de 90 graus.', 'Contraia o tronco levemente antes de mover um membro.', 'Levante um joelho de cada vez, mantendo a profundidade do agachamento na parede e as costas coladas nela.', 'Evite que a pélvis balance enquanto o braço ou a perna se move.', 'Reajuste sua postura antes de trocar de lado ou iniciar a próxima repetição.']),
  ('sVvXT5J', 'Flexão pike na bola suíça', array['Comece em posição de flexão com as mãos no chão e as canelas apoiadas na bola suíça.', 'Contraia o tronco e levante o quadril em direção ao teto, rolando a bola em direção às mãos.', 'Contraia o abdômen e os glúteos para que ombros, quadris e tornozelos se movam juntos.', 'Dobre os cotovelos para abaixar o peito, mantendo o corpo em linha reta.', 'Mantenha a bola firme e use os pés para controlar o equilíbrio.', 'Empurre de volta para a extensão total dos braços, mantendo a linha do corpo intacta.']),
  ('SxHteRW', 'Rosca alternada em pé com halteres', array['Fique em pé com os pés na largura dos ombros, segurando um halter em cada mão com as palmas voltadas para o corpo.', 'Mantenha sua coluna em uma posição neutra e confortável e o core ativado.', 'Comece com uma carga gerenciável e uma pequena flexão nos cotovelos.', 'Afaste os pesos do tronco até a altura dos ombros, mantendo os cotovelos levemente flexionados.', 'Termine o movimento de um lado antes que o outro lado comece.', 'Abaixe os braços lentamente para os lados sem balançar o peso; alterne os lados quando a série exigir.']),
  ('sxY5Biu', 'Rosca Scott Zottman unilateral com halter', array['Sente-se em um banco Scott e segure um halter em uma das mãos com a palma virada para cima.', 'Apoie a parte superior do braço no apoio do banco Scott, deixando o braço esticar totalmente.', 'Posicione o braço que está trabalhando contra o apoio do banco e deixe o cotovelo livre para dobrar.', 'Faça a rosca com as palmas para cima, vire as palmas para baixo no topo e abaixe com essa pegada pronada.', 'Mantenha ambos os ombros nivelados e evite virar o tronco em direção ao braço em movimento.', 'Abaixe até que os cotovelos estejam quase retos, mantendo a parte superior dos braços parada; alterne os lados quando a série exigir.']),
  ('sYCcnon', 'Extensão de tríceps unilateral em pé no cabo', array['Fique em pé com os pés na largura dos ombros, de frente para a polia.', 'Segure a manopla do cabo com a mão direita, com a palma virada para baixo, e posicione o braço de forma que fique reto e paralelo ao chão.', 'Posicione a parte superior dos braços no lugar antes de esticar os cotovelos.', 'Mantenha a parte superior dos braços firme e estenda através dos cotovelos para mover o peso.', 'Mantenha ambos os ombros nivelados e evite virar o tronco em direção ao braço em movimento.', 'Dobre os cotovelos lentamente para retornar ao início da próxima repetição; alterne os lados quando a série exigir.']),
  ('SYJ4Bkt', 'Rosca scott com barra', array['Sente-se em um banco scott com o peito apoiado no encosto e os braços estendidos sobre a borda, segurando uma barra com as palmas voltadas para cima', 'Com os braços imóveis, expire e flexione os pesos enquanto contrai os bíceps', 'Apoie a parte superior do braço no apoio do scott e deixe o cotovelo livre para dobrar', 'Flexione o peso enquanto a parte superior dos braços permanece em contato com o apoio', 'Mantenha o tronco firme e deixe a flexão do cotovelo erguer o peso', 'Abaixe até que os cotovelos estejam quase retos, mantendo a parte superior dos braços parada']),
  ('syUwUKY', 'Extensão de tríceps com halteres e pegada pronada', array['Sente-se em um banco ou cadeira com as costas retas e os pés apoiados', 'Pegue um halter com ambas as mãos, palmas voltadas para baixo, e estenda os braços para cima acima da cabeça', 'Posicione a parte superior dos braços no lugar antes de estender os cotovelos', 'Mantenha a parte superior dos braços firme e estenda através dos cotovelos para mover o peso', 'Mantenha a parte superior dos braços firme enquanto os antebraços se movimentam', 'Dobre os cotovelos lentamente para retornar ao início da próxima repetição']),
  ('szIn2UK', 'Abdominal remada negativa', array['Deite-se de costas com os joelhos flexionados e os pés apoiados', 'Coloque as mãos atrás da cabeça com os cotovelos apontados para fora', 'Posicione a pelve e mantenha o pescoço relaxado antes de curvar para cima', 'Curve a caixa torácica em direção à pelve, permitindo que os abdominais movam o tronco', 'Deixe um pequeno espaço entre o queixo e o peito; mantenha o movimento no tronco', 'Abaixe os ombros ou o tronco com controle antes da próxima flexão']),
  ('sZOR9EV', 'Rotação de tronco ajoelhada na máquina', array['Ajuste o assento ao seu corpo e acomode-se na máquina', 'Segure as manoplas ou as laterais da máquina para maior estabilidade', 'Posicione a pelve e realize a rotação através da caixa torácica', 'Gire através do tronco enquanto os quadris e a parte inferior do corpo permanecem o mais firmes possível', 'Mantenha a rotação suave em vez de jogar os braços através do corpo', 'Retorne pelo centro antes de girar para o outro lado']),
  ('SzX3uzM', 'Remada curvada com barra e pegada supinada', array['Fique em pé com os pés na largura dos ombros e joelhos flexionados', 'Segure uma barra com as palmas voltadas para baixo e as mãos logo acima da largura dos ombros', 'Posicione o tronco e permita que os braços alcancem a frente sem curvar excessivamente', 'Puxe os cotovelos para trás e traga a barra ou peso em direção ao tronco', 'Mantenha as palmas na pegada escolhida sem curvar os punhos para trás', 'Estenda os braços para a frente novamente sem deixar o tronco balançar']),
  ('T0yTjgW', 'Supino na máquina', array['Ajuste o assento ao seu corpo e acomode-se na máquina', 'Segure as manoplas com as palmas voltadas para baixo e posicione os cotovelos em um ângulo de 90 graus', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso ou as manoplas para longe enquanto mantém o tronco contraído', 'Mantenha os punhos alinhados e use uma trajetória de ombro que pareça natural', 'Abaixe o peso até a altura inicial com controle antes de empurrar novamente']),
  ('T2fA5Ir', 'Agachamento na bola bosu', array['Coloque a bola bosu no chão com o lado plano para cima', 'Fique em pé com os pés na largura dos ombros e posicione-se em cima da bola bosu', 'Contraia o abdômen e distribua a pressão por todo o pé', 'Flexione os quadris e joelhos para abaixar, mantendo os pés apoiados e os joelhos alinhados com os dedos dos pés', 'Empurre para cima com o peito e os quadris subindo juntos; evite que os joelhos caiam para dentro', 'Fique totalmente em pé, ajuste sua postura e respiração, então inicie a próxima descida']),
  ('T2mxWqc', ' Barra fixa com pegada supinada', array['Suspenda-se em uma barra fixa com as palmas voltadas para você e as mãos na largura dos ombros', 'Contraia o tronco e puxe o corpo em direção à barra, liderando com o peito', 'Inicie a partir de uma suspensão controlada com os ombros ativos em vez de relaxados', 'Puxe os cotovelos para baixo e traga a parte superior do peito em direção à barra sem chutar as pernas', 'Evite balançar as pernas para ultrapassar a barra', 'Abaixe até esticar os braços sem despencar do topo']),
  ('t8iSghb', 'Afundo com barra', array['Comece em pé com os pés na largura dos ombros e uma barra apoiada na parte superior das costas', 'Dê um passo à frente com o pé direito, mantendo o tronco erguido', 'Defina uma base ampla o suficiente para se equilibrar antes de flexionar qualquer um dos joelhos', 'Avance para o movimento e flexione ambos os joelhos, mantendo o pé da frente apoiado', 'Mantenha o pé da frente apoiado e evite que o joelho desabe para dentro', 'Empurre com o pé da frente para retornar ao início, depois alterne as pernas conforme planejado']),
  ('T8UpLkb', 'Barras com pegada mista', array['Segure a barra fixa com as palmas voltadas para cima e as mãos logo acima da largura dos ombros', 'Fique suspenso na barra com os braços esticados e os pés fora do chão', 'Comece de uma suspensão controlada com os ombros ativos em vez de relaxados', 'Puxe os cotovelos para baixo e aproxime a parte superior do peito da barra sem chutar as pernas', 'Evite balançar as pernas para ultrapassar a barra', 'Desça até os braços esticados sem despencar do topo']),
  ('TBNaSNs', 'Supino declinado com pegada fechada e barra EZ', array['Acomode-se em um banco declinado com a cabeça mais baixa que os pés', 'Segure a barra EZ com pegada fechada e palmas voltadas uma para a outra', 'Estabilize o tronco e alinhe os punhos com os antebraços', 'Empurre o peso para longe mantendo o tronco travado', 'Mantenha os punhos alinhados e use uma trajetória de ombro que pareça natural', 'Desça o peso até a altura inicial de forma controlada antes de empurrar novamente']),
  ('tBWXbIT', 'Crucifixo inclinado no cabo', array['Ajuste a máquina de cabo na posição baixa e prenda os alças', 'Sente-se em um banco inclinado com as costas apoiadas no encosto e os pés firmes', 'Mantenha uma leve flexão nos cotovelos e posicione os ombros antes de mover os braços', 'Com uma leve flexão nos cotovelos, junte os braços em um arco largo', 'Mantenha o ângulo do cotovelo praticamente inalterado durante o arco', 'Abra os braços de volta pelo mesmo arco sem deixar a carga cair']),
  ('tc5dYrf', 'Remada alta para posterior de ombro com elástico', array['Fique em pé com os pés na largura dos ombros e coloque o elástico sob os pés', 'Segure as alças do elástico com as palmas voltadas uma para a outra e os braços estendidos à frente', 'Posicione o tronco e permita que os braços avancem sem arredondar excessivamente', 'Puxe os cotovelos para trás e aproxime a alça ou o peso do tronco', 'Controle o elástico na volta em vez de deixar que ele puxe você de uma vez', 'Estenda os braços à frente novamente sem deixar o tronco balançar']),
  ('TDYiji6', 'Agachamento com salto', array['Fique em pé com os pés na largura dos ombros', 'Antes de se mover, abaixe o corpo em posição de agachamento flexionando os joelhos e empurrando o quadril para trás', 'Contraia o abdômen e distribua a pressão por todo o pé', 'Flexione o quadril e os joelhos para descer, mantendo os pés apoiados e os joelhos alinhados com os dedos dos pés', 'Empurre para cima com o peito e o quadril subindo juntos; evite que os joelhos desabem para dentro', 'Fique totalmente em pé, ajuste sua base e respiração, depois inicie a próxima descida']),
  ('TFA88iB', 'Elevação frontal com elástico', array['Fique em pé com os pés na largura dos ombros e segure o elástico à frente das coxas com as palmas para baixo', 'Mantenha os braços retos e, com controle, eleve-os para a frente até ficarem paralelos ao solo', 'Comece com uma carga gerenciável e uma pequena flexão nos cotovelos', 'Levante os braços para a frente até a altura dos ombros, mantendo as costelas para baixo e o tronco imóvel', 'Controle o elástico na volta em vez de deixar que ele puxe você de uma vez', 'Abaixe os braços lentamente para as laterais sem balançar o peso']),
  ('tFGKm99', 'Alongamento intermediário de flexores de quadril e quadríceps', array['Fique erguido com os pés na largura dos ombros', 'Use um objeto estável para apoio', 'Entre na posição inicial e respire calmamente antes de aprofundar o alongamento', 'Avance em direção ao alongamento até sentir uma tensão leve; continue respirando e evite balançar', 'Permaneça em um alongamento leve em vez de puxar mais com impulso', 'Mantenha a posição com respiração constante, depois solte suavemente; repita do outro lado se necessário']),
  ('TFqbd8t', 'Abdominal supra no solo', array['Deite de costas com os joelhos flexionados e os pés apoiados', 'Coloque as mãos atrás da cabeça com os cotovelos apontados para fora', 'Ajuste a pelve e mantenha o pescoço relaxado antes de subir', 'Flexione a caixa torácica em direção à pelve, deixando o abdômen mover o tronco', 'Deixe um pequeno espaço entre o queixo e o peito e mantenha o movimento no tronco', 'Abaixe os ombros ou o tronco com controle antes da próxima repetição']),
  ('tFToB7l', 'Prancha reversa com elevação de perna', array['Sente-se no chão com as pernas estendidas à frente e as mãos apoiadas atrás de você com os dedos apontando para os pés', 'Antes de se mover, force as mãos contra o chão e eleve o quadril, assumindo a posição de prancha reversa', 'Contraia o abdômen e encontre uma posição que possa manter sem prender a respiração', 'Contraia a região central e mantenha a posição respirando normalmente', 'Continue respirando de forma constante enquanto mantém a mesma linha corporal', 'Mantenha a postura pelo tempo planejado e depois saia dela com controle']),
  ('tgryw5Y', 'Flexão (na bola suíça)', array['Posicione a bola suíça no chão e fique de bruços com as mãos na bola, na largura dos ombros', 'Estique as pernas para trás, equilibrando-se na ponta dos pés', 'Contraia o abdômen e os glúteos para que ombros, quadris e tornozelos se movam juntos', 'Flexione os cotovelos para abaixar o peito, mantendo o corpo em linha reta', 'Mantenha a bola firme e use os pés para controlar o equilíbrio', 'Empurre para voltar aos braços estendidos, mantendo a linha do corpo intacta']),
  ('ThKP69G', 'Tríceps puxada com pegada inversa no cabo (barra W) (com arm blaster)', array['Conecte uma barra reta na polia alta da máquina de cabo', 'Fique de frente para a máquina em uma base estável com os pés na largura dos ombros', 'Fique a uma distância suficiente da pilha de pesos para manter o cabo tensionado', 'Mantenha os cotovelos próximos às costelas e estique os braços contra o cabo', 'Mantenha as palmas das mãos na pegada escolhida sem curvar os punhos para trás', 'Retorne suavemente à posição inicial antes de repetir']),
  ('TiaZTxx', 'Rosca sentada com halteres', array['Apoie ambos os pés no chão sentado em um banco, segurando um halter em cada mão com as palmas voltadas para a frente', 'Mantenha a coluna em uma posição neutra confortável e os cotovelos próximos ao tronco', 'Ajuste os ombros e os braços antes de flexionar os cotovelos', 'Flexione os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco', 'Mantenha o tronco parado e deixe a flexão do cotovelo levantar o peso', 'Abaixe até que os braços estejam quase esticados, mantendo a parte superior dos braços imóvel']),
  ('tig3PXb', 'Remada em pé com peso corporal e pegada fechada', array['Fique em pé com os pés na largura dos ombros e joelhos levemente flexionados', 'Incline-se para a frente na cintura, com a coluna firme e o core contraído', 'Ajuste o tronco e permita que os braços alcancem a frente sem curvar excessivamente as costas', 'Puxe os cotovelos para trás e traga a alça ou o peso em direção ao tronco', 'Traga os cotovelos para trás sem dar trancos no tronco', 'Estenda os braços para a frente novamente sem deixar o tronco balançar']),
  ('tj41Nu6', 'Leg press 45° com pés afastados', array['Ajuste o aparelho de leg press a um ângulo de 45 graus', 'Sente-se no aparelho com as costas apoiadas no encosto e os pés na plataforma', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso ou as alças para longe enquanto mantém o tronco contraído', 'Mantenha os punhos alinhados e use uma trajetória de ombro que pareça natural', 'Abaixe o peso até a altura inicial com controle antes de empurrar novamente']),
  ('tJ5nYqo', 'Rosca direta com barra W (com arm blaster)', array['Fique em pé com os pés na largura dos ombros e segure a barra W com as palmas voltadas para cima', 'Apoie os braços no arm blaster, mantendo-os estacionários durante todo o exercício', 'Ajuste os ombros e os braços antes de flexionar os cotovelos', 'Flexione os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco', 'Mantenha o tronco parado e deixe a flexão do cotovelo levantar o peso', 'Abaixe até que os braços estejam quase esticados, mantendo a parte superior dos braços imóvel']),
  ('tnaj0mT', 'Giro 360 com peso', array['Fique em pé com os pés na largura dos ombros e joelhos flexionados', 'Mantenha os braços estendidos à sua frente, paralelos ao chão', 'Posicione os ombros e deixe o peso ir para trás entre as pernas enquanto projeta o quadril', 'Projete o quadril para trás e depois empurre-o para a frente para elevar o peso, guiando com os braços', 'Deixe o quadril, e não os ombros, gerar a força', 'Deixe o peso cair naturalmente e faça o movimento do quadril novamente para o próximo balanço']),
  ('Tq6gbK6', 'Remada sentada com cabo', array['Sente-se na máquina de remada com cabo, com os pés apoiados e os joelhos flexionados', 'Segure as alças do cabo com as palmas voltadas para baixo', 'Posicione o tronco e permita que os braços se estendam para a frente sem curvar excessivamente', 'Puxe os cotovelos para trás e traga a alça ou o peso em direção ao tronco', 'Traga os cotovelos para trás sem dar trancos no tronco', 'Estenda os braços para a frente novamente sem deixar o tronco balançar']),
  ('trmte8s', 'Encolhimento com elástico', array['Fique em pé com os pés na largura dos ombros, coloque o elástico sob os pés e segure as pontas com as mãos', 'Mantenha os braços retos e relaxados, deixando o elástico pendurado à frente das coxas', 'Deixe os braços compridos e mantenha a cabeça neutra', 'Eleve os ombros em direção às orelhas sem dobrar os cotovelos ou girar os ombros', 'Controle o elástico na volta em vez de deixar que ele puxe você de uma vez', 'Retorne pelo mesmo caminho em ritmo controlado']),
  ('trqKQv2', 'Supino no Smith', array['Ajuste a altura da barra da máquina Smith na altura do peito', 'Acomode-se no banco com os pés firmemente apoiados no chão', 'Estabilize o tronco e alinhe os punhos com os antebraços', 'Empurre o peso para longe enquanto mantém o tronco firme', 'Mantenha os punhos alinhados e use uma trajetória de ombro que pareça natural', 'Abaixe o peso até a altura inicial com controle antes de empurrar novamente']),
  ('tTuZSDT', 'Puxada alta lateral unilateral na máquina', array['Ajuste o assento ao seu corpo e acomode-se na máquina', 'Segure a alça com as palmas voltadas para baixo e estenda totalmente o braço, mantendo uma leve flexão no cotovelo', 'Sente-se erguido e posicione os ombros antes de puxar a alça para baixo', 'Puxe a alça para baixo levando os cotovelos em direção às costelas e mantenha o tronco firme', 'Mantenha ambos os ombros nivelados e evite girar em direção ao braço que está trabalhando', 'Deixe a alça subir de forma constante até que os braços estejam estendidos, ajuste os ombros e alterne os lados quando necessário']),
  ('tuIZFDt', 'Prancha ajoelhada com toque no ombro', array['Comece em posição de joelhos com as mãos no chão, na largura dos ombros', 'Estenda as pernas para trás, apoiando-se nos dedos dos pés, e levante o corpo para uma posição de prancha', 'Contraia o abdômen e encontre uma posição que possa manter sem prender a respiração', 'Contraia a região central e mantenha a posição respirando normalmente', 'Continue respirando de forma constante enquanto mantém a mesma linha corporal', 'Mantenha a postura pelo tempo planejado e saia dela com controle']),
  ('TUZLh71', 'Agachamento com elástico', array['Fique em pé com os pés na largura dos ombros e o elástico posicionado logo acima dos joelhos', 'Com o peito estufado e o core contraído, empurre o quadril para trás e flexione os joelhos para agachar', 'Contraia o abdômen e distribua a pressão por todo o pé', 'Flexione o quadril e os joelhos para abaixar, mantendo os pés apoiados e os joelhos alinhados com os dedos dos pés', 'Controle o elástico na volta em vez de deixar que ele puxe você de uma vez', 'Fique totalmente em pé, ajuste sua postura e respiração, e inicie a próxima descida']),
  ('TV87DNB', 'Inchworm', array['Comece em pé com os pés na largura dos quadris', 'Antes de se mover, incline-se para a frente na cintura e coloque as mãos no chão à sua frente', 'Contraia o abdômen e mantenha a pelve encaixada antes de esticar os braços', 'Estenda os braços para a frente mantendo as costelas e a pelve alinhadas, parando antes que a parte inferior das costas arqueie', 'Pare de avançar quando a parte inferior das costas começar a arquear', 'Puxe de volta para o início usando os ombros e o abdômen, mantendo a mesma linha corporal']),
  ('TVdivgY', 'Desenvolvimento com halteres inclinado alternado', array['Sente-se em um banco inclinado com um halter em cada mão, apoiados nas coxas', 'Recline-se no banco e use as coxas para ajudar a erguer os halteres até a altura dos ombros, com as palmas voltadas para a frente', 'Firme o tronco e alinhe os punhos com os antebraços', 'Empurre o peso para cima mantendo o tronco firme', 'Finalize o movimento de um lado antes que o outro lado inicie', 'Abaixe o peso até a altura inicial com controle antes de empurrar novamente; alterne os lados quando necessário']),
  ('TXtXc84', 'Abdominal remador reverso com cabo', array['Conecte um cabo a uma polia baixa e deite-se de costas em um colchonete', 'Segure o cabo com as duas mãos e estenda os braços para cima do peito', 'Posicione a pelve e mantenha o pescoço relaxado antes de flexionar para cima', 'Flexione a caixa torácica em direção à pelve, permitindo que o abdômen mova o tronco', 'Deixe um pequeno espaço entre o queixo e o peito; mantenha o movimento no tronco', 'Abaixe os ombros ou o tronco com controle antes da próxima flexão']),
  ('tZkGYZ9', 'Abdominal bicicleta com elástico', array['Deite-se de costas com as mãos atrás da cabeça e os joelhos flexionados', 'Retire os pés do chão e traga o joelho direito em direção ao peito enquanto torce o tronco simultaneamente para aproximar o cotovelo esquerdo do joelho direito', 'Posicione a pelve e mantenha o pescoço relaxado antes de flexionar para cima', 'Traga um cotovelo em direção ao joelho oposto enquanto a outra perna se estende; alterne os lados em um ritmo constante', 'Controle o elástico na volta em vez de deixar que ele puxe você de volta', 'Abaixe os ombros ou o tronco com controle antes da próxima flexão']),
  ('tznL2Ad', 'Desenvolvimento duplo com kettlebell', array['Fique em pé com os pés na largura dos ombros, segurando um kettlebell em cada mão na altura dos ombros', 'Flexione levemente os joelhos e firme o tronco', 'Firme o tronco antes da puxada e mantenha a carga próxima ao corpo', 'Impulsione pelas pernas e quadris, depois guie o peso para a posição de recepção', 'Receba a carga com o tronco firme e os pés estáveis', 'Fique em pé para finalizar, depois abaixe o peso com controle antes da próxima repetição']),
  ('u0cNiij', 'Elevação pélvica baixa no chão', array['Deite-se de costas com os joelhos flexionados e os pés apoiados', 'Posicione os braços ao lado do corpo com as palmas voltadas para baixo', 'Apoie os pés e evite estufar as costelas enquanto os quadris se preparem para subir', 'Pressione através dos pés e eleve os quadris até que o tronco e as coxas fiquem alinhados', 'Pare quando os quadris estiverem alinhados com o tronco; não arqueie mais a região lombar', 'Abaixe os quadris de forma constante e mantenha os pés apoiados para o próximo movimento']),
