  ('VnfUNW7', 'Chin-up com pegada fechada', array['Segure a barra fixa com as palmas voltadas para você e as mãos na largura dos ombros', 'Suspenda-se na barra com os braços estendidos e os pés fora do chão', 'Comece de uma suspensão controlada com os ombros ativos e não relaxados', 'Puxe os cotovelos para baixo e traga a parte superior do peito em direção à barra sem chutar as pernas', 'Evite balançar as pernas para passar da barra', 'Abaixe até esticar os braços sem despencar do topo']),
  ('vNPJbDA', 'Extensão de tríceps inclinada com corda no cabo', array['Conecte uma corda a uma polia alta e ajuste o banco inclinado em um ângulo confortável', 'Fique de costas para a polia com uma base estável e os pés na largura dos ombros', 'Posicione a parte superior dos braços no lugar antes de estender os cotovelos', 'Mantenha a parte superior dos braços firme e estenda pelos cotovelos para mover o peso', 'Mantenha a parte superior dos braços firme enquanto os antebraços se movimentam', 'Flexione os cotovelos lentamente para retornar ao início da próxima repetição']),
  ('VO2qeJg', 'Abdução de quadril em prancha lateral', array['Comece deitado de lado com as pernas estendidas e empilhadas uma sobre a outra', 'Apoie-se no antebraço, mantendo o cotovelo diretamente abaixo do ombro', 'Contraia o abdômen e encontre uma posição que consiga manter sem prender a respiração', 'Mantenha a linha da prancha lateral e eleve a perna de cima sem deixar os quadris girarem para trás', 'Continue respirando de forma constante enquanto mantém a mesma linha corporal', 'Abaixe a perna sem deixar os quadris caírem, depois repita antes de trocar de lado']),
  ('vobtVkm', 'Alongamento de panturrilha com as mãos contra a parede', array['Fique de frente para uma parede com os pés na largura dos quadris', 'Apoie as mãos contra a parede na altura dos ombros', 'Acomode-se na posição inicial e respire calmamente antes de aprofundar o movimento', 'Aproxime-se do alongamento até sentir uma tensão leve; continue respirando e evite balançar', 'Mantenha-se em um alongamento leve em vez de puxar mais com impulso', 'Mantenha a posição com respiração constante, depois solte suavemente; repita do outro lado, se necessário']),
  ('vocve3e', 'Crucifixo unilateral com halteres na bola de exercício', array['Sente-se em uma bola de exercício com um halter em cada mão, palmas viradas uma para a outra.', 'Apoie um pé no chão e estenda a outra perna para a frente.', 'Mantenha uma leve flexão nos cotovelos e estabilize os ombros antes de mover os braços.', 'Com uma leve flexão nos cotovelos, junte os braços em um arco largo.', 'Mantenha a pelve nivelada enquanto a perna de apoio faz o trabalho.', 'Abra os braços de volta pelo mesmo arco sem deixar o peso cair; troque de lado quando necessário.']),
  ('vpleANJ', 'Pélvico com inclinação para ponte', array['Deite-se de costas com os joelhos flexionados e os pés apoiados.', 'Posicione os braços ao lado do corpo com as palmas voltadas para baixo.', 'Apoie os pés e evite estufar as costelas enquanto os quadris se preparam para subir.', 'Encaixe a pelve suavemente, depois empurre pelos pés para elevar os quadris em uma ponte.', 'Pare quando os quadris estiverem alinhados com o tronco; não arqueie mais a parte inferior das costas.', 'Abaixe os quadris de forma constante e mantenha os pés apoiados para a próxima elevação.']),
  ('vpp9Ku2', 'Remada unilateral sentada no cabo', array['Sente-se em um banco em frente a uma máquina de cabo com os pés apoiados e os joelhos flexionados.', 'Segure a alça com uma mão e mantenha o braço estendido à sua frente.', 'Estabilize o tronco e permita que os braços se estendam para a frente sem arredondar excessivamente.', 'Puxe os cotovelos para trás e traga a alça ou o peso em direção ao seu tronco.', 'Mantenha ambos os ombros nivelados e evite girar em direção ao braço que está trabalhando.', 'Estenda os braços para a frente novamente sem deixar o tronco balançar; troque de lado quando necessário.']),
  ('VPPtusI', 'Remada inclinada com joelhos flexionados', array['Prepare uma barra na altura da cintura e deite-se por baixo dela.', 'Segure a barra com as palmas voltadas para baixo, logo acima da largura dos ombros.', 'Estabilize o tronco e permita que os braços se estendam para a frente sem arredondar excessivamente.', 'Puxe os cotovelos para trás e traga a alça ou o peso em direção ao seu tronco.', 'Puxe os cotovelos para trás sem dar trancos no tronco.', 'Estenda os braços para a frente novamente sem deixar o tronco balançar.']),
  ('vpQaQkH', 'Esqui ergômetro', array['Ajuste a altura do assento e os apoios para os pés em uma posição confortável.', 'Segure as alças com as palmas voltadas para baixo.', 'Comece em um ritmo que permita que os pés e os braços se movam em sincronia.', 'Mova-se em um ritmo repetível, mantendo o movimento suave e a respiração constante.', 'Mantenha o padrão repetível à medida que a velocidade aumenta.', 'Mantenha o ritmo pelo intervalo planejado, diminuindo a velocidade se a forma começar a falhar.']),
  ('vptOQ4N', 'Flexão profunda', array['Comece em posição de prancha alta com as mãos logo acima da largura dos ombros e o corpo em linha reta.', 'Abaixe o peito em direção ao chão flexionando os cotovelos, mantendo-os próximos ao corpo.', 'Contraia o abdômen e os glúteos para que os ombros, quadris e tornozelos se movam juntos.', 'Flexione os cotovelos para abaixar o peito enquanto mantém o corpo em uma linha reta.', 'Mantenha a cabeça alinhada com a coluna enquanto os cotovelos flexionam.', 'Empurre de volta com os braços estendidos, mantendo a linha do corpo intacta.']),
  ('VQ3sNCn', 'Tríceps kickback unilateral sentado com halter', array['Apoie ambos os pés sentado em um banco; segure um halter em uma mão.', 'Incline o tronco para a frente na cintura, com a coluna firme e paralela ao chão.', 'Posicione os braços firmes antes de estender os cotovelos.', 'Segure o braço ao lado do seu tronco e estique o cotovelo para trás.', 'Mantenha ambos os ombros nivelados e evite girar em direção ao braço que está trabalhando.', 'Flexione os cotovelos lentamente para retornar ao início da próxima repetição; troque de lado quando necessário.']),
  ('vqsbmL0', 'Desenvolvimento na máquina', array['Ajuste a altura do assento e o encosto da máquina em uma posição confortável.', 'Sente-se na máquina com as costas apoiadas no encosto e os pés apoiados.', 'Contraia o tronco e alinhe os punhos com os antebraços.', 'Empurre o peso ou as alças para longe enquanto mantém o tronco contraído.', 'Mantenha os punhos alinhados e use uma trajetória de ombro que pareça natural.', 'Abaixe o peso até a altura inicial de forma controlada antes de empurrar novamente.']),
  ('vR1vold', 'Agachamento Zercher completo com barra', array['Posicione os pés na largura dos ombros com as pontas viradas levemente para fora', 'Segure a barra na dobra dos cotovelos com as mãos firmes para dar estabilidade', 'Contraia o abdômen e distribua a pressão por todo o pé', 'Flexione os quadris e joelhos para descer, mantendo os pés firmes e os joelhos alinhados com os dedos', 'Empurre para cima com o peito e quadris subindo juntos, evitando que os joelhos virem para dentro', 'Fique totalmente em pé, ajuste a base e a respiração, e inicie a descida seguinte']),
  ('VRBGPHB', 'Desenvolvimento de ombros no Smith', array['Ajuste o assento ao seu corpo e acomode-se na máquina', 'Segure a barra com as palmas voltadas para baixo, um pouco além da largura dos ombros', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso ou os puxadores mantendo o tronco firme', 'Mantenha os punhos alinhados e use um movimento natural para os ombros', 'Desça o peso até a altura inicial de forma controlada antes de empurrar novamente'])
